INSERT INTO `proposals` (`id`, `title`, `category`, `sector`, `description`, `deliverable`, `author_id`, `status`, `current_score`, `evaluations_count`, `created_at`) VALUES
('p1', 'Sistema de trazabilidad agrícola con blockchain', 'agritech', 'agro', 'Propuesta para implementar un sistema descentralizado que permita rastrear el origen, procesamiento y distribución de productos agrícolas usando tecnología blockchain. Se integra con sensores IoT para registro automático de cada etapa.', 'Prototipo funcional de plataforma web + API REST documentada + informe de viabilidad técnica y económica para el sector cafetero.', 'user1', 'good', 4.7, 47, '2026-08-01'),
('p10', 'Sistema de gestión de residuos inteligente con IoT', 'circular-economy', 'environment', 'Red de contenedores con sensores de llenado y clasificación automática que optimiza rutas de recolección y reporta en tiempo real a operadores. Incluye app ciudadana de reporte.', 'Firmware para microcontroladores + backend de rutas + app móvil + piloto en 1 municipio.', 'u18', 'evaluating', 3.6, 15, '2026-09-01'),
('p11', 'App de mapeo comunitario para acceso a servicios públicos', 'smart-cities', 'government', 'Herramienta de cartografía participativa donde los ciudadanos georreferencia deficiencias en servicios públicos (agua, luz, vías) y las instituciones hacen seguimiento en un panel centralizado.', 'App móvil offline-first + panel de gestión institucional + API de integración con SIGOT.', 'u5', 'good', 4.6, 44, '2026-08-08'),
('p12', 'Motor de recomendación de cultivos con datos climáticos', 'agritech', 'agro', 'Sistema que cruza datos climáticos del IDEAM, precios de mercado y preferencias del agricultor para recomendar el portafolio de cultivos óptimo por temporada.', 'API de recomendación + dashboard web + app Android ligera para agricultores.', 'u15', 'evaluating', 3.7, 12, '2026-09-03'),
('p13', 'Red de intercambio de conocimiento entre investigadores', 'open-data', 'education', 'Plataforma de repositorio y networking para investigadores latinoamericanos con sistema de validación de pares, métricas de impacto y búsqueda semántica de publicaciones.', 'Portal web + motor de búsqueda semántico + sistema de reputación + piloto con 5 universidades.', 'u16', 'good', 4.5, 36, '2026-08-22'),
('p14', 'Plataforma de economía circular para residuos industriales', 'circular-economy', 'environment', 'Marketplace B2B que conecta empresas generadoras de residuos industriales aprovechables con transformadores locales, con trazabilidad completa y certificación de impacto ambiental.', 'Plataforma web B2B + sistema de certificación + dashboard de impacto + integración RNEC.', 'u14', 'needs-improvement', 2.2, 14, '2026-08-30'),
('p15', 'Sistema predictivo de mantenimiento para infraestructura vial', 'smart-cities', 'mobility', 'Modelo de ML que analiza imágenes satelitales y reportes ciudadanos para priorizar inversión en mantenimiento vial municipal, con un horizonte de predicción de 6 meses.', 'Modelo predictivo + API de consulta + integración con sistemas de INVIAS + piloto en 2 municipios.', 'u13', 'evaluating', 4.0, 21, '2026-09-02'),
('p16', 'Laboratorio de innovación abierta para pymes manufactureras', 'digital-transformation', 'government', 'Espacio virtual y físico de co-creación que ofrece a pymes manufactureras acceso a herramientas de diseño, prototipado digital y mentorías de transformación industrial 4.0.', 'Plataforma de matching mentor-empresa + catálogo de recursos + 3 casos de transformación documentados.', 'u9', 'evaluating', 3.7, 17, '2026-09-05'),
('p17', 'Fintech de ahorro programado para trabajadores informales', 'fintech', 'fintech', 'App de ahorro automático que detecta picos de ingreso en trabajadores informales (conductores, vendedores, domiciliarios) y reserva micro-montos para fondos de emergencia y pensión voluntaria.', 'App móvil + motor de detección de ingresos + integración PSE/Nequi + prueba con 200 usuarios.', 'u9', 'good', 4.7, 58, '2026-08-15'),
('p18', 'Red de monitoreo ambiental ciudadano de bajo costo', 'sustainability', 'environment', 'Dispositivos de medición de calidad del aire y agua de fabricación local (< $30 USD) conectados a una red comunitaria que publica datos abiertos en tiempo real.', 'Diseño de hardware abierto + firmware + plataforma de datos + piloto con 50 sensores en 3 ciudades.', 'u28', 'evaluating', 3.9, 11, '2026-09-08'),
('p19', 'Plataforma de gestión de ensayos clínicos en Colombia', 'health-tech', 'health', 'Sistema digital para gestión, seguimiento y reporting de ensayos clínicos según la normativa INVIMA, con módulos de consentimiento informado electrónico y trazabilidad de muestras.', 'Plataforma web + app de campo para investigadores + módulo de reportes INVIMA + piloto con 2 IPS.', 'u8', 'good', 4.5, 40, '2026-08-20'),
('p2', 'Marketplace de servicios para microempresarios rurales', 'digital-economy', 'fintech', 'Plataforma digital que conecta microempresarios de zonas rurales con compradores urbanos, eliminando intermediarios y facilitando pagos digitales inclusivos con soporte para zonas sin conectividad estable.', 'Aplicación móvil multiplataforma con módulo de pagos integrado y soporte offline básico.', 'u2', 'evaluating', 3.5, 28, '2026-08-10'),
('p20', 'Sistema de gamificación para educación financiera', 'edtech', 'education', 'Juego serio para jóvenes de 14-22 años que enseña conceptos de presupuesto, ahorro e inversión mediante simulaciones de decisiones financieras reales, con progresión adaptativa.', 'Videojuego web + guía docente + integración con currículos MEN + prueba con 500 estudiantes.', 'u25', 'evaluating', 4.0, 24, '2026-09-04'),
('p21', 'Marketplace de carbono para pequeños productores', 'sustainability', 'environment', 'Plataforma que certifica y monetiza bonos de carbono generados por prácticas sostenibles de pequeños agricultores, con verificación satelital y trazabilidad blockchain.', 'Plataforma web + módulo de verificación + integración con registros internacionales + piloto con 30 productores.', 'u27', 'needs-improvement', 2.5, 9, '2026-09-10'),
('p22', 'Plataforma de gestión de proyectos para juntas de acción comunal', 'digital-transformation', 'government', 'Herramienta digital simple para que las JAC puedan planificar, presupuestar y reportar proyectos comunitarios, con generación automática de informes para alcaldías.', 'App web + app móvil + plantillas de proyectos + integración con sistema de rendición de cuentas.', 'u10', 'evaluating', 3.4, 8, '2026-09-12'),
('p23', 'Sistema de irrigación inteligente con ML para ahorro hídrico', 'agritech', 'agro', 'Controlador de riego automatizado que combina pronósticos climáticos, humedad del suelo en tiempo real y modelos de evapotranspiración para reducir el consumo de agua hasta un 40%.', 'Hardware de control + firmware + dashboard agrícola + validación en 5 fincas piloto.', 'u21', 'good', 4.7, 35, '2026-08-28'),
('p24', 'Hub digital de turismo comunitario en zonas de posconflicto', 'digital-economy', 'government', 'Plataforma de promoción y reserva de experiencias de turismo rural y comunitario en municipios de posconflicto, con integración de pagos digitales y sistema de calificación.', 'Portal web + app turista + panel de operadores + integración ProColombia + piloto en 4 municipios PDET.', 'u20', 'evaluating', 4.0, 18, '2026-09-07'),
('p25', 'Red de bibliotecas digitales comunitarias sin internet', 'edtech', 'education', 'Sistema de distribución de contenidos educativos (libros, videos, software) mediante redes mesh WiFi locales sin depender de internet externo, administrado por la propia comunidad.', 'Software de nodo mesh + catálogo de contenidos curado + guía de instalación + piloto en 6 veredas.', 'u25', 'good', 4.6, 29, '2026-09-05'),
('p3', 'Asistente de IA para diagnóstico de suelos colombianos', 'agritech', 'agro', 'Modelo de machine learning entrenado con datos edafológicos de 12 regiones de Colombia para recomendar cultivos óptimos según perfil de suelo, temperatura y precipitación histórica.', 'Modelo ML + API de inferencia + guía de uso para extensionistas agrícolas del ICA.', 'u3', 'needs-improvement', 2.3, 31, '2026-07-28'),
('p4', 'Red de innovación ciudadana para movilidad sostenible', 'smart-cities', 'mobility', 'Comunidad digital de ciudadanos que co-diseñan soluciones de movilidad sostenible para su municipio, con mapa colaborativo de rutas y puntos críticos.', 'Portal web + guía metodológica de co-diseño + piloto documentado en 2 municipios del Eje Cafetero.', 'u4', 'evaluating', 3.8, 22, '2026-08-20'),
('p5', 'Plataforma de telemedicina rural con IA predictiva', 'health-tech', 'health', 'Sistema de teleconsulta médica con módulo de IA que analiza síntomas reportados por pacientes rurales y sugiere diagnósticos preliminares, reduciendo desplazamientos innecesarios a centros de salud.', 'App móvil + dashboard médico web + modelo de triaje predictivo con precisión >82%.', 'u12', 'good', 4.6, 52, '2026-08-05'),
('p6', 'Sistema de microcréditos algorítmicos para emprendedores', 'fintech', 'fintech', 'Motor de scoring crediticio alternativo que evalúa el historial de comportamiento digital, ventas en plataformas y reputación en redes para otorgar microcréditos sin historial bancario.', 'Motor de scoring + panel de riesgo + integración con 2 entidades microfinancistas piloto.', 'u11', 'good', 4.5, 39, '2026-08-12'),
('p7', 'Hub de energía solar comunitaria descentralizada', 'sustainability', 'energy', 'Modelo de negocio cooperativo para instalar paneles solares compartidos en comunidades rurales de baja tensión, con facturación automática y distribución de excedentes.', 'Modelo financiero + prototipo de sistema de medición IoT + estudio de viabilidad para 3 comunidades piloto en Nariño.', 'u6', 'good', 4.8, 61, '2026-07-25'),
('p8', 'Plataforma adaptativa de educación STEM rural', 'edtech', 'education', 'LMS adaptativo con contenidos STEM en español y lenguas nativas que se ajusta al nivel y ritmo de cada estudiante. Funciona con conectividad limitada y en dispositivos de gama baja.', 'Plataforma web-offline + app Android + banco de 200 ejercicios STEM + piloto con 3 instituciones rurales.', 'u7', 'good', 4.4, 33, '2026-08-18'),
('p9', 'Observatorio de datos abiertos territoriales', 'open-data', 'government', 'Portal de visualización de indicadores socioeconómicos municipales con datos del DANE, DNP y entidades territoriales, actualización automática vía API y panel ciudadano de seguimiento.', 'Portal web responsive + pipeline de ingesta automatizada + 15 dashboards temáticos + guía de uso ciudadano.', 'u20', 'evaluating', 3.7, 19, '2026-08-25'),
('sp0025', 'Observatorio de seguridad alimentaria con datos abiertos', 'agritech', 'health', 'Portal de visualización y análisis de indicadores de seguridad alimentaria con fuentes de datos públicas actualizadas. Propuesta del sector health con enfoque en seguridad alimentaria, orientada a investigadores.', 'Motor de recomendación + integración con 3 sistemas existentes + informe de impacto.', 'su0088', 'evaluating', 3.95, 3, '2026-02-23'),
('sp0026', 'App de energía renovable offline-first para zonas rurales', 'digital-economy', 'fintech', 'Aplicación móvil que funciona sin conectividad permanente y resuelve necesidades de energía renovable en zonas apartadas. Propuesta del sector fintech con enfoque en energía renovable, orientada a organizaciones sociales.', 'Prototipo funcional + documentación técnica + piloto en 2 municipios.', 'su0404', 'good', 4.44, 13, '2026-04-15'),
('sp0027', 'Laboratorio de innovación en economía solidaria', 'edtech', 'government', 'Espacio virtual de co-creación y prototipado rápido enfocado en economía solidaria para comunidades locales. Propuesta del sector government con enfoque en economía solidaria, orientada a microempresarios.', 'Plataforma web + modelo ML entrenado + manual de implementación.', 'su0106', 'evaluating', 3.45, 32, '2026-04-12'),
('sp0028', 'Laboratorio de innovación en patrimonio cultural', 'health-tech', 'education', 'Espacio virtual de co-creación y prototipado rápido enfocado en patrimonio cultural para comunidades locales. Propuesta del sector education con enfoque en patrimonio cultural, orientada a alcaldías municipales.', 'Motor de recomendación + integración con 2 sistemas existentes + informe de impacto.', 'su0193', 'evaluating', 3.82, 13, '2026-05-17'),
('sp0029', 'Sistema inteligente de formación técnica con IA', 'circular-economy', 'health', 'Solución basada en inteligencia artificial para optimizar procesos de formación técnica en el sector health. Propuesta del sector health con enfoque en formación técnica, orientada a pacientes crónicos.', 'Hardware prototipo + firmware + aplicación de gestión + piloto de 3 semanas.', 'su0155', 'evaluating', 3.93, 8, '2026-02-20'),
('sp0030', 'Motor de predicción de gestión del agua con ML', 'sustainability', 'agro', 'Modelo de machine learning que anticipa tendencias y riesgos en gestión del agua para apoyar la toma de decisiones. Propuesta del sector agro con enfoque en gestión del agua, orientada a trabajadores informales.', 'Portal web responsive + 5 dashboards temáticos + datos abiertos vinculados.', 'su0486', 'evaluating', 3.61, 17, '2026-08-19'),
('sp0031', 'Laboratorio de innovación en logística rural', 'circular-economy', 'energy', 'Espacio virtual de co-creación y prototipado rápido enfocado en logística rural para comunidades locales. Propuesta del sector energy con enfoque en logística rural, orientada a cooperativas.', 'App móvil + API REST + informe de validación con 4 usuarios reales.', 'su0196', 'evaluating', 3.35, 40, '2026-04-15'),
('sp0032', 'App de comercio electrónico offline-first para zonas rurales', 'health-tech', 'energy', 'Aplicación móvil que funciona sin conectividad permanente y resuelve necesidades de comercio electrónico en zonas apartadas. Propuesta del sector energy con enfoque en comercio electrónico, orientada a instituciones educativas.', 'Motor de recomendación + integración con 3 sistemas existentes + informe de impacto.', 'su0050', 'good', 4.0, 20, '2026-03-04'),
