('sp0335', 'Motor de predicción de biodiversidad con ML', 'circular-economy', 'government', 'Modelo de machine learning que anticipa tendencias y riesgos en biodiversidad para apoyar la toma de decisiones. Propuesta del sector government con enfoque en biodiversidad, orientada a jóvenes rurales.', 'App móvil + API REST + informe de validación con 3 usuarios reales.', 'su0260', 'evaluating', 3.54, 5, '2026-02-05'),
('sp0336', 'Laboratorio de innovación en salud preventiva', 'sustainability', 'fintech', 'Espacio virtual de co-creación y prototipado rápido enfocado en salud preventiva para comunidades locales. Propuesta del sector fintech con enfoque en salud preventiva, orientada a cooperativas.', 'App móvil + API REST + informe de validación con 3 usuarios reales.', 'su0429', 'good', 4.11, 10, '2026-06-20'),
('sp0337', 'App de identidad digital offline-first para zonas rurales', 'digital-economy', 'agro', 'Aplicación móvil que funciona sin conectividad permanente y resuelve necesidades de identidad digital en zonas apartadas. Propuesta del sector agro con enfoque en identidad digital, orientada a instituciones educativas.', 'Prototipo funcional + documentación técnica + piloto en 4 municipios.', 'su0073', 'good', 4.08, 19, '2026-07-16'),
('sp0338', 'Laboratorio de innovación en acceso a justicia', 'circular-economy', 'environment', 'Espacio virtual de co-creación y prototipado rápido enfocado en acceso a justicia para comunidades locales. Propuesta del sector environment con enfoque en acceso a justicia, orientada a alcaldías municipales.', 'Hardware prototipo + firmware + aplicación de gestión + piloto de 5 semanas.', 'su0102', 'evaluating', 3.36, 9, '2026-06-12'),
('sp0339', 'Laboratorio de innovación en mipymes rurales', 'health-tech', 'environment', 'Espacio virtual de co-creación y prototipado rápido enfocado en mipymes rurales para comunidades locales. Propuesta del sector environment con enfoque en mipymes rurales, orientada a comunidades indígenas.', 'App móvil + API REST + informe de validación con 2 usuarios reales.', 'su0165', 'evaluating', 3.59, 27, '2026-02-06'),
('sp0340', 'Laboratorio de innovación en gestión del agua', 'fintech', 'agro', 'Espacio virtual de co-creación y prototipado rápido enfocado en gestión del agua para comunidades locales. Propuesta del sector agro con enfoque en gestión del agua, orientada a alcaldías municipales.', 'Plataforma web + modelo ML entrenado + manual de implementación.', 'u11', 'good', 4.75, 16, '2026-04-24'),
('sp0341', 'Red colaborativa de empleo juvenil territorial', 'sustainability', 'agro', 'Ecosistema de actores locales articulados para impulsar empleo juvenil en territorios priorizados. Propuesta del sector agro con enfoque en empleo juvenil, orientada a artesanos.', 'Hardware prototipo + firmware + aplicación de gestión + piloto de 2 semanas.', 'su0356', 'evaluating', 3.47, 20, '2026-06-09'),
('sp0342', 'Hub de acceso a justicia para pymes del sector energy', 'digital-transformation', 'energy', 'Plataforma de recursos, herramientas y conexiones especializadas en acceso a justicia para pequeñas y medianas empresas. Propuesta del sector energy con enfoque en acceso a justicia, orientada a comunidades indígenas.', 'Hardware prototipo + firmware + aplicación de gestión + piloto de 3 semanas.', 'su0474', 'good', 4.57, 22, '2026-03-01'),
('sp0343', 'Plataforma de movilidad urbana para mujeres emprendedoras', 'digital-economy', 'fintech', 'Sistema digital que permite a mujeres emprendedoras acceder y gestionar movilidad urbana de forma eficiente. Propuesta del sector fintech con enfoque en movilidad urbana, orientada a mujeres emprendedoras.', 'Portal web responsive + 2 dashboards temáticos + datos abiertos vinculados.', 'su0267', 'good', 4.24, 17, '2026-04-09'),
('sp0344', 'Motor de predicción de transparencia fiscal con ML', 'open-data', 'education', 'Modelo de machine learning que anticipa tendencias y riesgos en transparencia fiscal para apoyar la toma de decisiones. Propuesta del sector education con enfoque en transparencia fiscal, orientada a organizaciones sociales.', 'Plataforma web + modelo ML entrenado + manual de implementación.', 'su0269', 'evaluating', 3.46, 29, '2026-03-04'),
('sp0345', 'Plataforma de movilidad urbana para cooperativas', 'circular-economy', 'education', 'Sistema digital que permite a cooperativas acceder y gestionar movilidad urbana de forma eficiente. Propuesta del sector education con enfoque en movilidad urbana, orientada a cooperativas.', 'Portal web responsive + 2 dashboards temáticos + datos abiertos vinculados.', 'su0251', 'evaluating', 3.89, 9, '2026-08-02'),
('sp0346', 'App de innovación social offline-first para zonas rurales', 'agritech', 'mobility', 'Aplicación móvil que funciona sin conectividad permanente y resuelve necesidades de innovación social en zonas apartadas. Propuesta del sector mobility con enfoque en innovación social, orientada a organizaciones sociales.', 'Hardware prototipo + firmware + aplicación de gestión + piloto de 2 semanas.', 'su0433', 'good', 4.12, 18, '2026-04-02'),
('sp0347', 'Laboratorio de innovación en transparencia fiscal', 'digital-transformation', 'environment', 'Espacio virtual de co-creación y prototipado rápido enfocado en transparencia fiscal para comunidades locales. Propuesta del sector environment con enfoque en transparencia fiscal, orientada a jóvenes rurales.', 'App móvil + API REST + informe de validación con 3 usuarios reales.', 'su0447', 'evaluating', 3.87, 29, '2026-05-13'),
('sp0348', 'Ecosistema de comercio electrónico bajo economía circular', 'agritech', 'health', 'Modelo de negocio regenerativo que integra los principios de economía circular en la cadena de comercio electrónico. Propuesta del sector health con enfoque en comercio electrónico, orientada a cooperativas.', 'App móvil + API REST + informe de validación con 5 usuarios reales.', 'su0260', 'evaluating', 3.68, 17, '2026-08-08'),
('sp0349', 'Red colaborativa de seguridad alimentaria territorial', 'digital-economy', 'government', 'Ecosistema de actores locales articulados para impulsar seguridad alimentaria en territorios priorizados. Propuesta del sector government con enfoque en seguridad alimentaria, orientada a pacientes crónicos.', 'Motor de recomendación + integración con 4 sistemas existentes + informe de impacto.', 'su0413', 'good', 5.0, 16, '2026-08-26');
